    const types: Array<'GOVERNANCE' | 'REPLAY' | 'IDENTITY' | 'TELEMETRY' | 'POLICY'> = ['GOVERNANCE', 'REPLAY', 'IDENTITY', 'POLICY', 'TELEMETRY'];
